        exp = 0
        power_p = p
        while power_p <= n:
            exp += n // power_p
            if power_p > n // p: break
            power_p *= p
        return exp

    def get_exponent(n, p):
        if n == 0: return 0
        exp = 0
        while n > 0 and n % p == 0:
            exp += 1
            n //= p
        return exp

